    /// <param name="queue">a queue to add the new SDL_AsyncIO to.</param>
    /// <param name="userdata">an app-defined pointer that will be provided with the task results.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_LoadFileAsync")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    [return: MarshalAs(UnmanagedType.U1)]
    public static partial bool LoadFileAsync(byte* file, AsyncIOQueue queue, void* userdata);

    /// <summary>Load all the data from a file path, asynchronously.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_LoadFileAsync</c>.</para>
    /// <para>
    /// This function returns as quickly as possible; it does not wait for the read to complete. On a successful return,
    /// this work will continue in the background. If the work begins, even failure is asynchronous: a failing return
    /// value from this function only means the work couldn't start at all.
    /// </para>
    /// <para>
    /// The data is allocated with a zero byte at the end (null terminated) for convenience. This extra byte is not
    /// included in SDL_AsyncIOOutcome's bytes_transferred value.
    /// </para>
    /// <para>
    /// This function will allocate the buffer to contain the file. It must be deallocated by calling SDL_free() on
    /// SDL_AsyncIOOutcome's buffer field after completion.
    /// </para>
    /// <para>
    /// An SDL_AsyncIOQueue must be specified. The newly-created task will be added to it when it completes its work.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_LoadFile_IO</c>.</para>
    /// </remarks>
    /// <param name="file">the path to read all available data from.</param>
    /// <param name="queue">a queue to add the new SDL_AsyncIO to.</param>
    /// <param name="userdata">an app-defined pointer that will be provided with the task results.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public static bool LoadFileAsync(ReadOnlySpan<byte> file, AsyncIOQueue queue, void* userdata)
    {
        using var fileUtf8 = new NulTerminatedUtf8(file, stackalloc byte[NulTerminatedUtf8.StackLength]);
        fixed (byte* filePtr = fileUtf8)
        {
            return LoadFileAsync(filePtr, queue, userdata);
        }
    }
}
